// === Get all input items ===
const items = $input.all();

// === Add upload date ===
const now = new Date();
const formattedDate = `${now.getMonth() + 1}/${now.getDate()}/${now.getFullYear()}`;

// === Process all leads ===
let results = [];

for (const item of items) {
  let raw = item.json.output;

  if (!raw) continue;

  // Remove markdown formatting
  raw = raw.replace(/```json|```/g, '').trim();

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    console.error("JSON parse failed:", e);
    continue;
  }

  // Handle both array and single object output
  const leads = Array.isArray(parsed) ? parsed : [parsed];

  for (const lead of leads) {
    results.push({
      json: {
        name: lead.name || "",
        email: lead.email || "",
        message: lead.message || lead.notes || "",
        budget: lead.budget || "",
        category: lead.category || "",
        intent: lead.intent || "",
        summary: lead.summary || "",
        date: formattedDate || "",
        submission_type: lead.submission_type 
      }
    });
  }
}

return results;
